#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int h, n;
    cin >> h >> n;

    int low = 1;
    int high = (1 << h); // 2^h
    int ans = 0;
    int move = 0; // 0 or 1

    while (low < high) {
        int mid = low + (high - low) / 2;

        if (n <= mid) {
            if (move == 0) {
                ans += 1;
                move ^= 1;
            } else {
                ans += (1 << h); // 2^h
            }
            high = mid;
        } else {
            if (move == 1) {
                ans += 1;
                move ^= 1;
            } else {
                ans += (1 << h); // 2^h
            }
            low = mid + 1;
        }
        h--;
    }

    cout << ans << "\n";

    return 0;
}
